<?php
namespace Semizzy\Addons\Education\Models;
use Illuminate\Database\Eloquent\Model;
final class EducationProgrammeAdmission extends Model { protected $table='education_programme_admissions'; protected $guarded=[]; protected $casts=['utme_available'=>'boolean','direct_entry_available'=>'boolean','other_entry_available'=>'boolean','first_choice_required'=>'boolean','metadata'=>'array','verified_at'=>'datetime','published_at'=>'datetime']; public function programme(){return $this->belongsTo(EducationProgramme::class);} public function academicSession(){return $this->belongsTo(EducationAcademicSession::class,'academic_session_id');} public function routes(){return $this->belongsToMany(EducationAdmissionRoute::class,'education_programme_admission_routes','programme_admission_id','admission_route_id');} public function requirements(){return $this->hasMany(EducationAdmissionRequirement::class,'programme_admission_id');} public function cutoffs(){return $this->hasMany(EducationAdmissionCutoff::class,'programme_admission_id');} public function screeningRules(){return $this->hasMany(EducationAdmissionScreeningRule::class,'programme_admission_id');} public function specialRules(){return $this->hasMany(EducationAdmissionSpecialRule::class,'programme_admission_id');} public function documents(){return $this->hasMany(EducationAdmissionDocument::class,'programme_admission_id');} public function sources(){return $this->hasMany(EducationAdmissionSource::class,'programme_admission_id');}}
